//! TF_DS_COMPRESS2_PAIR_ONCE (off by default; takes effect only under TF_DS_FUSED_COMPRESS2_NORM, which production
//! sets): the 0197 decode compressor computes each distinct ratio-2 source pair once a window. Rows whose ordered pair
//! of resolved source slots matches get the same softmax pair sum and the same normalized latent row (the output is a
//! function of the pair's resolved bytes alone), so the key's first row computes it and writes every matching row's
//! output row; every input row still writes its own raw-ring slot. Pure: no cuda import; the kernels are
//! tf_ds_compress2x_norm{128,512}_pair_kernel (dsv41_torch.cu, beside 0197's), the launcher Exact.compress2xNormPair,
//! the call site round.zig's decode ratio-2 chain. A malformed switch refuses startup.
const std = @import("std");

pub const env_name: [:0]const u8 = "TF_DS_COMPRESS2_PAIR_ONCE";

/// The switch's value: unset, "" or "0" off; "1" on; anything else is a refusal to start (the message is on stderr).
pub fn parse(text: ?[]const u8) ?bool {
    const t = text orelse return false;
    if (t.len == 0 or std.mem.eql(u8, t, "0")) return false;
    if (std.mem.eql(u8, t, "1")) return true;
    std.debug.print("{s}: expected 1 or 0\n", .{env_name});
    return null;
}

pub fn fromText(text: ?[]const u8) error{BadCompress2PairOnce}!bool {
    return parse(text) orelse error.BadCompress2PairOnce;
}

/// Whether the pair-once arm serves this shape: the 0197 decode widths and any nonzero row count. The call site keeps
/// 0197's per-row kernel when the switch is off or the shape is unsupported.
pub fn works(on: bool, rows: usize, d: usize) bool {
    return on and rows > 0 and (d == 128 or d == 512);
}

// -- host reference: the pair key's grouping rule (rounds.py _ix / round.zig setGlue's gi) ---------------------------

/// setGlue's gi pair for a row at position `p` of stream `slot` (`raw` is the raw ring's per-stream rows, 64 at the
/// served config): the pair's two raw-ring source slots, wrapping modulo `raw` inside the stream's slot range.
pub fn pairKey(p: i64, slot: i64, raw: i64) [2]i64 {
    const groups = @divFloor(p, 2);
    const base = slot * raw;
    return .{ base + @mod(groups * 2, raw), base + @mod(groups * 2 + 1, raw) };
}

/// Two rows share one pair computation iff their keys are equal. The key carries the stream's slot base, so rows from
/// different requests never share even at equal positions.
pub fn sharePair(a: [2]i64, b: [2]i64) bool {
    return a[0] == b[0] and a[1] == b[1];
}

/// The distinct pair computations (pair-once blocks that compute) over one stream's row positions: rows at positions
/// `2k` and `2k + 1` share the pair `k`, and a window edge can leave one member outside the window.
pub fn distinctPairs(pos: []const i64, slot: i64, raw: i64) usize {
    var keys: [64][2]i64 = undefined;
    var n: usize = 0;
    for (pos) |p| {
        const k = pairKey(p, slot, raw);
        var seen = false;
        for (keys[0..n]) |e| if (sharePair(e, k)) {
            seen = true;
            break;
        };
        if (!seen) {
            keys[n] = k;
            n += 1;
        }
    }
    return n;
}

// -- tests -----------------------------------------------------------------------------------------------------------

const expectEqual = std.testing.expectEqual;

test "the switch parses its forms and nothing else" {
    try expectEqual(false, parse(null).?);
    try expectEqual(false, parse("").?);
    try expectEqual(false, parse("0").?);
    try expectEqual(true, parse("1").?);
    try expectEqual(@as(?bool, null), parse("2"));
    try expectEqual(@as(?bool, null), parse("yes"));
    try expectEqual(@as(?bool, null), parse("01"));
    try std.testing.expectEqual(@as(bool, true), try fromText("1"));
    try std.testing.expectError(error.BadCompress2PairOnce, fromText("2"));
}

test "works takes the 0197 decode widths and any nonzero rows" {
    for ([_]usize{ 128, 512 }) |d| {
        for ([_]usize{ 1, 7, 28, 48 }) |rows| try std.testing.expect(works(true, rows, d));
    }
    try std.testing.expect(!works(false, 7, 512));
    try std.testing.expect(!works(true, 0, 512));
    for ([_]usize{ 64, 256, 1024, 2048 }) |d| try std.testing.expect(!works(true, 7, d));
}

test "pairKey is setGlue's gi rule, including the raw-ring wrap" {
    // positions 2k and 2k + 1 name the same pair; the pair's slots are the stream's own range
    try expectEqual([_]i64{ 0, 1 }, pairKey(0, 0, 64));
    try expectEqual([_]i64{ 0, 1 }, pairKey(1, 0, 64));
    try expectEqual([_]i64{ 2, 3 }, pairKey(2, 0, 64));
    try expectEqual([_]i64{ 2, 3 }, pairKey(3, 0, 64));
    try expectEqual([_]i64{ 62, 63 }, pairKey(63, 0, 64));
    // wrap: position 64's pair is slots 0, 1 again (its own raw row is slot 0, the partner's slot 1)
    try expectEqual([_]i64{ 0, 1 }, pairKey(64, 0, 64));
    try expectEqual([_]i64{ 0, 1 }, pairKey(65, 0, 64));
    // stream 1's range is 64..128
    try expectEqual([_]i64{ 64, 65 }, pairKey(0, 1, 64));
    try expectEqual([_]i64{ 66, 67 }, pairKey(3, 1, 64));
}

test "rows of different requests never share a pair" {
    var p: i64 = 0;
    while (p < 70) : (p += 1) {
        try std.testing.expect(!sharePair(pairKey(p, 0, 64), pairKey(p, 1, 64)));
        try std.testing.expect(!sharePair(pairKey(p, 1, 64), pairKey(p, 2, 64)));
        try std.testing.expect(!sharePair(pairKey(p, 0, 64), pairKey(p + 64, 1, 64)));
    }
}

test "a contiguous window computes ceil-half the pairs: 7 rows is four" {
    // the served seven-row verify window at both starting parities; one stream, positions p..p + 6
    for ([_]i64{ 0, 1, 61, 62 }) |p| {
        var pos: [7]i64 = undefined;
        for (&pos, 0..) |*q, i| q.* = p + @as(i64, @intCast(i));
        try expectEqual(@as(usize, 4), distinctPairs(&pos, 0, 64));
    }
    // 5 rows: three pairs at either parity; 6 rows: three (even start) or four (odd start)
    const p5e = [_]i64{ 0, 1, 2, 3, 4 };
    const p5o = [_]i64{ 1, 2, 3, 4, 5 };
