// These three steps mirror the instructions and reduction order of the pinned kit.
__device__ __forceinline__ float tf_ds_kit_squares4(float a, float b, float c, float d) {
    float sum = __fmul_rn(b, b);
    sum = __fmaf_rn(a, a, sum);
    sum = __fmaf_rn(c, c, sum);
    return __fmaf_rn(d, d, sum);
}

__device__ __forceinline__ float tf_ds_kit_warp_sum(float sum) {
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1)
        sum = __fadd_rn(sum, __shfl_xor_sync(0xffffffffu, sum, offset));
    return sum;
}

template<int D>
__device__ __forceinline__ float tf_ds_kit_inverse_rms(float sum, float eps) {
    const float mean_eps = __fmaf_rn(sum, 1.0f / D, eps);
    float root, inv;
    asm("sqrt.approx.ftz.f32 %0, %1;" : "=f"(root) : "f"(mean_eps));
    asm("div.approx.f32 %0, %1, %2;" : "=f"(inv) : "f"(1.0f), "f"(root));
    return inv;
}

// Decode RMSNorm, specialized to the two matching _rmsnorm cubins in kit abe07c7d.
// Each of the 128 threads loads one contiguous group. The 512-wide cubin starts with
// lane element 1 squared, then contracts elements 0, 2 and 3 into that sum.
// PRELOAD: the caller read its weight element before griddepcontrol.wait (fixed model weights only).
template<int D, bool PRELOAD = false>
__device__ __forceinline__ void tf_ds_triton_rmsnorm_row(const __nv_bfloat16* src, const __nv_bfloat16* w,
                                                         __nv_bfloat16* dst, float eps, __nv_bfloat16 wv = 0) {
    static_assert(D == 128 || D == 512, "missing kit specialization");
    constexpr int items = D / 128;
    const int tid = threadIdx.x;
    const int base = tid * items;
    float x[items];
    #pragma unroll
    for (int j = 0; j < items; ++j) x[j] = __bfloat162float(src[base + j]);
    float sum;
    if (D == 512) sum = tf_ds_kit_squares4(x[0], x[1], x[2], x[3]);
    else sum = __fmul_rn(x[0], x[0]);
    sum = tf_ds_kit_warp_sum(sum);
    __shared__ float warp_sum[4];
    __shared__ float inv;
    if ((tid & 31) == 0) warp_sum[tid >> 5] = sum;
    __syncthreads();
    if (tid < 4) {
        sum = warp_sum[tid];
        sum = __fadd_rn(sum, __shfl_xor_sync(0xfu, sum, 2));
        sum = __fadd_rn(sum, __shfl_xor_sync(0xfu, sum, 1));
        if (tid == 0) inv = tf_ds_kit_inverse_rms<D>(sum, eps);
    }
    __syncthreads();
    #pragma unroll
    for (int j = 0; j < items; ++j) {
        const float y = __fmul_rn(x[j], inv);
        dst[base + j] = __float2bfloat16_rn(__fmul_rn(__bfloat162float(PRELOAD ? wv : w[base + j]), y));
    }
}

// tf_ds_rms_norm_kernel's reduction on one row held in `src` (bf16), L = blockDim.x matches rmsLanes(D, rows): the
// four per-lane accumulators, the L > 32 shared fold, the shuffle down, and torch's mean/epsilon/rsqrt. Returns the
// row's reciprocal, which the shared `rs` publishes to every thread. Extra y lanes help produce and store the row;
// only y == 0 participates in the sum.
__device__ __forceinline__ float tf_ds_torch_rmsnorm_inv(const __nv_bfloat16* src, int D, float factor, float eps) {
    __shared__ float red[512];
    __shared__ float rs;
    const int L = blockDim.x;
    const int lane = threadIdx.x + L * threadIdx.y;
    float acc0 = 0.f, acc1 = 0.f, acc2 = 0.f, acc3 = 0.f;
    for (int idx = lane < L ? lane : D / 4; idx * 4 + 3 < D; idx += L) {
        const float a = __bfloat162float(src[idx * 4 + 0]);
        const float b = __bfloat162float(src[idx * 4 + 1]);
        const float c = __bfloat162float(src[idx * 4 + 2]);
        const float d = __bfloat162float(src[idx * 4 + 3]);
        acc0 = __fadd_rn(acc0, __fmul_rn(a, a));
        acc1 = __fadd_rn(acc1, __fmul_rn(b, b));
        acc2 = __fadd_rn(acc2, __fmul_rn(c, c));
        acc3 = __fadd_rn(acc3, __fmul_rn(d, d));
    }
    float v = __fadd_rn(__fadd_rn(__fadd_rn(acc0, acc1), acc2), acc3);
    int dim_x = L;
    if (L > 32) {
        if (lane < L) red[lane] = v;
        for (int offset = L / 2; offset >= 32; offset >>= 1) {
            __syncthreads();
            if (lane < offset && lane + offset < L) {
                v = __fadd_rn(v, red[lane + offset]);
                red[lane] = v;
            }
        }
        dim_x = 32;
        // Shared `red` is read only by the fold above and the reduction below is registers and shuffles, so the
        // barrier is kept only for the folded shapes (whose last iteration ends on a shared write): at L == 32 no
        // thread writes `red` at all. The `rs` publication barrier below stays for every shape.
        __syncthreads();
    }
    for (int offset = dim_x >> 1; offset > 0; offset >>= 1) v = __fadd_rn(v, __shfl_down_sync(TF_FULL_MASK, v, offset));
    if (lane == 0) rs = rsqrtf(__fadd_rn(__fmul_rn(v, factor), eps));
    __syncthreads();
    return rs;
}

// The same norm's store over `src`, one element a loop step from `lane` by `threads` (the caller's flattened index).
__device__ __forceinline__ void tf_ds_torch_rmsnorm_row(const __nv_bfloat16* src, const __nv_bfloat16* w,
                                                        __nv_bfloat16* dst, int D, float factor, float eps) {
    const float r = tf_ds_torch_rmsnorm_inv(src, D, factor, eps);
    const int lane = threadIdx.x + blockDim.x * threadIdx.y;
    const int threads = blockDim.x * blockDim.y;
    for (int j = lane; j < D; j += threads) {
        const float y = __fmul_rn(__bfloat162float(src[j]), r);
        dst[j] = __float2bfloat16_rn(__fmul_rn(__bfloat162float(w[j]), y));
    }
}

